def longest_increasing_subsequence(sequences):
    # Initialize a list to store the lengths of increasing subsequences ending at each index
    dp = [1] * len(sequences)

    # Iterate through each sequence
    for i in range(1, len(sequences)):
        # Update the length of the longest increasing subsequence ending at the current index
        for j in range(i):
            if sequences[i] > sequences[j]:
                dp[i] = max(dp[i], dp[j] + 1)

    # The maximum value in the dp list represents the length of the longest increasing subsequence
    return max(dp)

