def perfect_squares(upper_limit, lower_limit):
    # Initialize an empty list to store perfect squares
    perfect_squares = []

    # Iterate through the range from lower_limit to upper_limit
    for num in range(lower_limit, upper_limit + 1):
        # Check if the square root of the number is an integer
        if int(num**0.5)**2 == num:
            # If it is, add the number to the list of perfect squares
            perfect_squares.append(num)

    return perfect_squares

def polar_rect(θ, r):
    # Convert polar coordinates to rectangular coordinates
    x = r * cos(θ)
    y = r * sin(θ)
    return (x, y)

def removezero_ip(ips):
    # Split the input string into a list of strings using '.' as the delimiter
    parts = ips.split('.')
    # Initialize an empty list to store the modified parts
    modified_parts = []
    # Iterate over each part in the list
    for part in parts:
        # Check if the part is not empty and starts with '0'
        if part and part[0] == '0':
            # If it does, append an empty string to the modified list
            modified_parts.append('')
        else:
            # Otherwise, append the part as is
            modified_parts.append(part)
    # Join the modified parts back into a single string with '.' as the delimiter
    return '.'.join(modified_parts)

def diff_even_odd(ary):
    # Initialize variables to store the first even and odd numbers
    even = None
    odd = None

    # Iterate through the array to find the first even and odd numbers
    for num in ary:
        if num % 2 == 0:
            even = num
        else:
            odd = num

    # Calculate the difference between the first even and odd numbers
    if even is not None and odd is not None:
        return even - odd
    else:
        return "No even or odd numbers found"

